 private EditText address,port;private TextView state;private Button check,install,connectExisting;private CheckBox pinRoot;private String target;private int targetPort;private KeyPair identity;private boolean queue,agent,busy;private String boot;
 private static final Set<String> FILES=new HashSet<>(Arrays.asList("station-panel-v2","station-matrix","matrix-probe","station-tv.apk","controller.apk","controller.json","station-tv.json","privapp-permissions-station-studio.xml","station-panel.rc","station-matrix.rc","rootd-cpu0.rc","yandexstation_2.yaml"));
