 private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(0xfffaf9fd);getWindow().setNavigationBarColor(0xfffaf9fd);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(24),dp(28),dp(24),dp(32));page.setBackgroundColor(0xfffaf9fd);TextView title=new TextView(this);title.setText("Установить AliceKit\nна рутированную станцию");title.setTextSize(27);title.setTextColor(0xff28232f);page.addView(title);TextView detail=new TextView(this);detail.setText("Телефон и станция — в одной домашней сети. Нужен уже работающий ADB с root или совместимый Hybrid Root. Проверенный профиль: Станция Макс · Android 9 · 5000000921. Компьютер не требуется.");detail.setTextSize(15);detail.setTextColor(0xff847a91);detail.setPadding(0,dp(18),0,dp(20));page.addView(detail);address=new EditText(this);address.setHint("IP станции, например 192.168.1.100");address.setSingleLine();address.setInputType(InputType.TYPE_CLASS_PHONE);page.addView(address);port=new EditText(this);port.setHint("Порт ADB");port.setText("5556");port.setSingleLine();port.setInputType(InputType.TYPE_CLASS_NUMBER);page.addView(port);check=new Button(this);check.setText("Проверить подключение и root");check.setOnClickListener(v->check());page.addView(check);state=new TextView(this);state.setText("Сначала проверим доступ без изменения станции. Если ADB запросит подтверждение, разрешите телефон на станции.");state.setTextSize(14);state.setTextColor(0xff62556f);state.setPadding(0,dp(18),0,dp(18));page.addView(state);pinRoot=new CheckBox(this);pinRoot.setText("Исправить автозапуск совместимого Hybrid Root 1.2.4");pinRoot.setChecked(false);page.addView(pinRoot);install=new Button(this);install.setText("Установить и перезапустить станцию");install.setEnabled(false);install.setOnClickListener(v->{new AlertDialog.Builder(this).setTitle("Установка на "+target).setMessage("Будет установлен проверенный комплект AliceKit для Max 5000000921. Установщик создаст резервные копии своих заменяемых файлов. Станция перезапустится. Аккаунты и пользовательские приложения сохраняются. Требуется 260 МБ свободного места в /data и 25 МБ в /odm.").setPositiveButton("Установить",(d,w)->install()).setNegativeButton("Отмена",null).show();});LinearLayout.LayoutParams actionSpace=new LinearLayout.LayoutParams(-1,-2);actionSpace.topMargin=dp(12);actionSpace.bottomMargin=dp(12);page.addView(install,actionSpace);connectExisting=new Button(this);connectExisting.setText("Подключить к установленной панели");connectExisting.setVisibility(View.GONE);connectExisting.setOnClickListener(v->{if(!busy)complete();});page.addView(connectExisting);Button back=new Button(this);back.setText("Вернуться к поиску");back.setOnClickListener(v->{if(!busy)finish();});page.addView(back);ScrollView scroll=new ScrollView(this);scroll.setFitsSystemWindows(true);scroll.addView(page);setContentView(scroll);}
 private void message(String text){runOnUiThread(()->state.setText(text));}
 private void busy(boolean value){busy=value;runOnUiThread(()->{check.setEnabled(!value);address.setEnabled(!value);port.setEnabled(!value);pinRoot.setEnabled(!value);install.setEnabled(!value&&target!=null);connectExisting.setEnabled(!value&&target!=null);});}
 private KeyPair identity()throws Exception{if(identity!=null)return identity;KeyFactory factory=KeyFactory.getInstance("RSA");File privateFile=new File(getFilesDir(),"kontur-adb-private"),publicFile=new File(getFilesDir(),"kontur-adb-public");if(privateFile.isFile()&&publicFile.isFile()){identity=new KeyPair(factory.generatePublic(new X509EncodedKeySpec(read(publicFile,8192))),factory.generatePrivate(new PKCS8EncodedKeySpec(read(privateFile,8192))));}else{KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);identity=generator.generateKeyPair();try(FileOutputStream out=openFileOutput(privateFile.getName(),MODE_PRIVATE)){out.write(identity.getPrivate().getEncoded());}try(FileOutputStream out=openFileOutput(publicFile.getName(),MODE_PRIVATE)){out.write(identity.getPublic().getEncoded());}}return identity;}
 private String shell(String command)throws Exception{try(NativeAdb adb=new NativeAdb(target,targetPort,identity())){return adb.shell(command);}}
 private void push(String name,byte[] data)throws Exception{try(NativeAdb adb=new NativeAdb(target,targetPort,identity())){adb.push(name,data);}}
 private void verify()throws Exception{String[] fields=shell("getprop ro.product.device; getprop ro.build.version.incremental; getprop ro.build.version.sdk; id -u; cat /sys/fs/selinux/enforce; cat /proc/sys/kernel/random/boot_id").split("\n");if(fields.length!=6||!fields[0].equals("yandexstation_2")||!fields[1].equals("5000000921")||!fields[2].equals("28"))throw new IOException("Для этой модели или сборки нет проверенного профиля. Изменений нет.");queue=!fields[3].equals("0");if(queue){String status=shell("cat /data/local/tmp/rootstatus 2>/dev/null || true");if(!status.contains("state=PROTECTED")||!status.contains("profile=0921"))throw new IOException("ADB доступен, но root не подтверждён. Сначала завершите получение root в AliceBridge.");}if(!fields[4].equals("0"))throw new IOException("Root-профиль ещё не переведён в Permissive. Проверьте состояние AliceBridge.");boot=fields[5];agent=shell("test -f /odm/bin/station-panel-v2 && test -f /odm/etc/init/station-panel.rc && echo installed || echo absent").equals("installed");}
 private void check(){if(busy)return;try{String value=address.getText().toString().trim();if(!value.matches("[0-9.]+"))throw new Exception("Укажите локальный IPv4-адрес станции");target=value;targetPort=Integer.parseInt(port.getText().toString());if(targetPort<1||targetPort>65535)throw new Exception();}catch(Exception e){target=null;message("Проверьте IP-адрес и порт ADB");return;}busy(true);message("Проверяем модель, сборку и root…");new Thread(()->{try{verify();message(agent?"Root подтверждён. Панель уже установлена. Подключите телефон по коду на станции.":"Совместимая Станция Макс. Root подтверждён"+(queue?" через защищённую очередь Hybrid Root.":" напрямую через ADB.")+" Можно установить комплект.");runOnUiThread(()->{install.setText(agent?"Обновить комплект и перезапустить":"Установить и перезапустить станцию");connectExisting.setVisibility(agent?View.VISIBLE:View.GONE);});}catch(Exception e){target=null;message(e.getMessage()==null?"ADB не ответил. Проверьте адрес, порт и разрешение для телефона.":e.getMessage());}finally{busy(false);}},"kontur-root-check").start();}
 private static byte[] read(File file,int max)throws Exception{try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>max)throw new IOException("Слишком большой файл комплекта");}return out.toByteArray();}}
 private static String sha(byte[] b)throws Exception{return PublicUpdates.hex(MessageDigest.getInstance("SHA-256").digest(b));}
 private Map<String,byte[]> unpack(byte[] zip)throws Exception{Map<String,byte[]> entries=new HashMap<>();int total=0,count=0;try(ZipInputStream in=new ZipInputStream(new ByteArrayInputStream(zip))){ZipEntry entry;while((entry=in.getNextEntry())!=null){String name=entry.getName();if(++count>512||name.contains("..")||name.startsWith("/")||name.contains("\\")||entries.containsKey(name))throw new IOException("Некорректный комплект установки");if(entry.isDirectory())continue;ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);total+=n;if(out.size()>32*1024*1024||total>96*1024*1024)throw new IOException("Комплект слишком большой");}if(name.equals("manifest.json")||name.equals("install-device.sh")||name.equals("rollback-device.sh")||name.startsWith("payload/"))entries.put(name,out.toByteArray());}}return entries;}
 private void root(String script,String stage,boolean wait)throws Exception{if(!queue){try(NativeAdb adb=new NativeAdb(target,targetPort,identity())){adb.timeout(180000);adb.shell(script);}return;}String id="studio-"+UUID.randomUUID().toString().replace("-","").substring(0,16),name=stage+"/request.sh";push(name,(script+"\n").getBytes("UTF-8"));shell("chown 2000:2000 "+name+" && chmod 0660 "+name+" && mv "+name+" /data/local/tmp/rootcmd-"+id);if(!wait)return;long deadline=System.currentTimeMillis()+180000;while(System.currentTimeMillis()<deadline){String reply=shell("cat /data/local/tmp/rootres."+id+" 2>/dev/null || true");if(!reply.isEmpty()){Map<String,String> fields=new HashMap<>();for(String line:reply.split("\n")){int i=line.indexOf('=');if(i>0)fields.put(line.substring(0,i),line.substring(i+1));}if(!id.equals(fields.get("id"))||!boot.equals(fields.get("boot_id"))||!"executed".equals(fields.get("status"))||!"exited".equals(fields.get("result"))||!"0".equals(fields.get("exit"))||!"0".equals(fields.get("signal"))||!"0".equals(fields.get("truncated")))throw new IOException("Rootd не подтвердил успешную установку. Проверьте результат перед повтором.");return;}Thread.sleep(700);}throw new IOException("Нет подтверждения rootd. Установка автоматически не повторяется.");}
 private void install(){if(busy)return;final boolean pin=pinRoot.isChecked();busy(true);new Thread(()->{String stage=null;try{verify();message("Загружаем подписанный каталог выпуска…");JSONObject release=PublicUpdates.manifest(),artifact=release.optJSONObject("station");if(artifact==null||!artifact.optString("profile").equals("max-0921"))throw new IOException("В текущем общем выпуске ещё нет подписанного профиля установки с телефона. Обновите приложение и повторите позже.");message("Загружаем комплект "+release.getString("versionName")+"…");byte[] bundle=PublicUpdates.fetch(artifact.getString("url"),64*1024*1024);if(bundle.length!=artifact.getLong("size")||!sha(bundle).equals(artifact.getString("sha256")))throw new IOException("Подпись каталога верна, но хеш комплекта не совпал");Map<String,byte[]> entries=unpack(bundle);bundle=null;if(!entries.containsKey("manifest.json")||!entries.containsKey("install-device.sh"))throw new IOException("Неполный установщик");JSONObject manifest=new JSONObject(new String(entries.get("manifest.json"),"UTF-8"));Set<String> found=new HashSet<>();Iterator<String> it=manifest.keys();while(it.hasNext())found.add(it.next());if(!found.equals(FILES))throw new IOException("Неизвестный состав профиля");for(String name:FILES){byte[] data=entries.get("payload/"+name);if(data==null||!sha(data).equals(manifest.getString(name)))throw new IOException("Повреждён файл: "+name);}message("Загружаем оригинальный YAM…");byte[] yam=PublicUpdates.fetch(YAM,24*1024*1024);if(!sha(yam).equals(YAM_SHA))throw new IOException("Хеш YAM не совпал");verify();long needed=260000L*1024+yam.length;for(String name:FILES)needed+=entries.get("payload/"+name).length;String[] disk=shell("df -k /data | tail -n 1").trim().split("\\s+");if(disk.length<4||Long.parseLong(disk[3])*1024<needed)throw new IOException("Освободите минимум "+((needed+1048575)/1048576)+" МБ в /data перед установкой");stage="/data/local/tmp/station-studio-install-"+UUID.randomUUID().toString().replace("-","").substring(0,16);shell("mkdir -p "+stage);StringBuilder sums=new StringBuilder();for(String name:FILES){message("Передаём: "+name);push(stage+"/"+name,entries.get("payload/"+name));sums.append(manifest.getString(name)).append(' ').append(name).append('\n');}push(stage+"/yam",yam);sums.append(YAM_SHA).append(" yam\n");push(stage+"/SHA256SUMS",sums.toString().getBytes("US-ASCII"));push(stage+"/install-device.sh",entries.get("install-device.sh"));message("Устанавливаем комплект. Не отключайте питание станции…");root("set -eu\n/system/bin/sh "+stage+"/install-device.sh "+stage+" "+(pin?"1":"0"),stage,true);agent=true;message("Установка подтверждена. Перезапускаем станцию…");if(queue){String rebootStage="/data/local/tmp/station-studio-install-"+UUID.randomUUID().toString().replace("-","").substring(0,16);shell("mkdir -p "+rebootStage);root("setprop sys.powerctl reboot",rebootStage,false);}else{try{shell("setprop sys.powerctl reboot");}catch(Exception ignored){/* Connection loss is expected after this single reboot request. */}}long deadline=System.currentTimeMillis()+180000;boolean ready=false;while(System.currentTimeMillis()<deadline){Thread.sleep(4000);try{String current=shell("cat /proc/sys/kernel/random/boot_id; getprop sys.boot_completed");if(!current.startsWith(boot+"\n")&&current.endsWith("\n1")){ready=true;break;}}catch(Exception ignored){}}if(!ready)throw new IOException("Установка подтверждена, но запуск после перезагрузки ещё не подтверждён. Вернитесь к поиску станции; не повторяйте установку.");shell("am start -n local.station.studio/.TvActivity");message("Станция запущена. На ней откройте «Настройки → Подключить телефон», затем подключитесь по коду.");runOnUiThread(()->{connectExisting.setVisibility(View.VISIBLE);install.setText("Обновить комплект и перезапустить");});}catch(Exception e){message((e.getMessage()==null?"Связь прервалась":e.getMessage())+"\nАвтоматический повтор не выполняется.");}finally{busy(false);}},"kontur-install").start();}
 private void complete(){setResult(RESULT_OK,new Intent().putExtra("host",target));finish();}
